"use client";
/* Astronaut, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Astronaut(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("astronaut"); }, []);
  return React.createElement("piix-sprite", { "name": "astronaut", ...piixAttrs(props) });
}

export default Astronaut;
